@startuml

class City {
  + Name : string
}

class H2SLocation {
  + Name : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class ScheduledPickup {
  + Description : string
  + RequestedDay : date
  + PickupTimeWindow : string
}

class Vehicle {
  + StorageSpace : float
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class PickupRoute {
  + Date : date
}

class DistributionCenter {
}

class FoodBank {
}

class H2SEmployee {
}

class Article {
  + Description : string
  + Category : string
  + RFIDTag : string
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class Category {
}

H2SLocation "*" -- "1" City
H2SLocation "1" *-- "1" DistributionCenter
H2SLocation "1" *-- "0..1" FoodBank

Resident "1" -- "*" ScheduledPickup
ScheduledPickup "*" -- "1" Vehicle
VolunteerDriver "*" -- "1" Vehicle
PickupRoute "1" -- "1" Vehicle
PickupRoute "1" -- "*" ScheduledPickup

Vehicle "*" -- "1" DistributionCenter
Vehicle "*" -- "1" FoodBank

DistributionCenter "1" -- "*" Article
H2SEmployee "1" -- "*" Article
Category "1" -- "*" Article

Client "1" -- "*" Article
H2SEmployee "1" -- "*" Client

@enduml

